-- =============================================
-- V2.5: Todo 및 Event에 그룹(GROUP_ID) 추가
-- =============================================

-- 1. TB_TODO에 GROUP_ID 컬럼 추가
ALTER TABLE TB_TODO
    ADD COLUMN GROUP_ID BIGINT NULL COMMENT '그룹 ID' AFTER PARENT_TODO_ID;

-- TB_TODO GROUP_ID 인덱스
CREATE INDEX IDX_TODO_GROUP ON TB_TODO(GROUP_ID);

-- TB_TODO GROUP_ID FK
ALTER TABLE TB_TODO
    ADD CONSTRAINT FK_TODO_GROUP FOREIGN KEY (GROUP_ID) REFERENCES TB_GROUP(GROUP_ID) ON DELETE SET NULL;

-- 2. TB_EVENT에 GROUP_ID 컬럼 추가
ALTER TABLE TB_EVENT
    ADD COLUMN GROUP_ID BIGINT NULL COMMENT '그룹 ID' AFTER PARENT_EVENT_ID;

-- TB_EVENT GROUP_ID 인덱스
CREATE INDEX IDX_EVENT_GROUP ON TB_EVENT(GROUP_ID);

-- TB_EVENT GROUP_ID FK
ALTER TABLE TB_EVENT
    ADD CONSTRAINT FK_EVENT_GROUP FOREIGN KEY (GROUP_ID) REFERENCES TB_GROUP(GROUP_ID) ON DELETE SET NULL;
